import { randomUUID } from 'node:crypto';
import type { DatabaseSync, SQLOutputValue } from 'node:sqlite';

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

/** Attempts allowed in total, including the first. */
export const MAX_ATTEMPTS = 3;
/** A worker heartbeat older than this means the worker is down. */
export const WORKER_STALE_MS = 3000;

/** A row of the `jobs` table, as stored. */
export interface JobRow {
  seq: number;
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  progress_completed: number;
  output: string | null;
  error: string | null;
  payload: string | null;
  available_at: number;
  created_at: string;
  updated_at: string;
}

/** The job as returned by the HTTP API. */
export interface JobJson {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

export interface NewJob {
  input: string;
  steps: number;
  failAttempts: number;
}

const COLUMNS = 'seq, id, status, input, steps, fail_attempts, attempts, progress_completed, output, error, payload, available_at, created_at, updated_at';

export function toJson(r: JobRow): JobJson {
  return {
    id: r.id,
    status: r.status,
    input: r.input,
    steps: r.steps,
    failAttempts: r.fail_attempts,
    attempts: r.attempts,
    progress: { completed: r.progress_completed, total: r.steps },
    result: r.status === 'completed' && r.output !== null ? { output: r.output } : null,
    error: r.status === 'failed' ? (r.error ?? 'transient failure') : null,
    createdAt: r.created_at,
    updatedAt: r.updated_at,
  };
}

/** Runs `fn` inside an immediate write transaction, so concurrent writers from other processes wait. */
export function inTransaction<T>(db: DatabaseSync, fn: () => T): T {
  db.exec('BEGIN IMMEDIATE');
  try {
    const result = fn();
    db.exec('COMMIT');
    return result;
  } catch (err) {
    db.exec('ROLLBACK');
    throw err;
  }
}

function one(rows: Record<string, SQLOutputValue> | undefined): JobRow | undefined {
  return rows as unknown as JobRow | undefined;
}

export function getJob(db: DatabaseSync, id: string): JobRow | undefined {
  return one(db.prepare(`SELECT ${COLUMNS} FROM jobs WHERE id = ?`).get(id));
}

function getJobBySeq(db: DatabaseSync, seq: number): JobRow | undefined {
  return one(db.prepare(`SELECT ${COLUMNS} FROM jobs WHERE seq = ?`).get(seq));
}

export function listJobs(db: DatabaseSync): JobRow[] {
  return db.prepare(`SELECT ${COLUMNS} FROM jobs ORDER BY seq DESC`).all() as unknown as JobRow[];
}

export function findByIdempotencyKey(db: DatabaseSync, key: string): JobRow | undefined {
  return one(db.prepare(`SELECT ${COLUMNS} FROM jobs WHERE idempotency_key = ?`).get(key));
}

export function insertJob(db: DatabaseSync, job: NewJob, idempotencyKey: string | null, payload: string): JobRow {
  const id = randomUUID();
  const ts = new Date().toISOString();
  db.prepare(
    `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress_completed, idempotency_key, payload, available_at, created_at, updated_at)
     VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, ?, 0, ?, ?)`,
  ).run(id, job.input, job.steps, job.failAttempts, idempotencyKey, payload, ts, ts);
  return getJob(db, id)!;
}

/** Puts jobs left `running` by a previous worker back in the queue. Only one worker runs at a time. */
export function requeueInterrupted(db: DatabaseSync): number {
  const result = db
    .prepare(`UPDATE jobs SET status = 'queued', progress_completed = 0, available_at = 0, updated_at = ? WHERE status = 'running'`)
    .run(new Date().toISOString());
  return Number(result.changes);
}

/** Atomically takes the oldest queued job that is due, and starts an attempt on it. */
export function claimNext(db: DatabaseSync, nowMs: number): JobRow | undefined {
  return inTransaction(db, () => {
    const next = db
      .prepare(`SELECT seq FROM jobs WHERE status = 'queued' AND available_at <= ? ORDER BY seq LIMIT 1`)
      .get(nowMs) as unknown as { seq: number } | undefined;
    if (!next) return undefined;
    db.prepare(
      `UPDATE jobs SET status = 'running', attempts = attempts + 1, progress_completed = 0, updated_at = ? WHERE seq = ?`,
    ).run(new Date().toISOString(), next.seq);
    return getJobBySeq(db, next.seq);
  });
}

export function setProgress(db: DatabaseSync, seq: number, completed: number): void {
  db.prepare(`UPDATE jobs SET progress_completed = ?, updated_at = ? WHERE seq = ?`).run(
    completed,
    new Date().toISOString(),
    seq,
  );
}

export function completeJob(db: DatabaseSync, seq: number, output: string): void {
  db.prepare(
    `UPDATE jobs SET status = 'completed', output = ?, error = NULL, progress_completed = steps, updated_at = ? WHERE seq = ?`,
  ).run(output, new Date().toISOString(), seq);
}

/** Records a failed attempt: requeue with a delay while attempts remain, otherwise mark the job failed. */
export function failAttempt(db: DatabaseSync, job: JobRow, nowMs: number, retryDelayMs: number): void {
  const ts = new Date().toISOString();
  if (job.attempts >= MAX_ATTEMPTS) {
    db.prepare(
      `UPDATE jobs SET status = 'failed', error = 'transient failure', progress_completed = 0, updated_at = ? WHERE seq = ?`,
    ).run(ts, job.seq);
  } else {
    db.prepare(
      `UPDATE jobs SET status = 'queued', progress_completed = 0, available_at = ?, updated_at = ? WHERE seq = ?`,
    ).run(nowMs + retryDelayMs, ts, job.seq);
  }
}

export function writeHeartbeat(db: DatabaseSync, nowMs: number): void {
  db.prepare(
    `INSERT INTO heartbeats (name, at) VALUES ('worker', ?) ON CONFLICT(name) DO UPDATE SET at = excluded.at`,
  ).run(nowMs);
}

export function clearHeartbeat(db: DatabaseSync): void {
  db.prepare(`DELETE FROM heartbeats WHERE name = 'worker'`).run();
}

export function workerIsUp(db: DatabaseSync, nowMs: number): boolean {
  const row = db.prepare(`SELECT at FROM heartbeats WHERE name = 'worker'`).get() as unknown as { at: number } | undefined;
  return row !== undefined && nowMs - row.at <= WORKER_STALE_MS;
}

