import { setInterval as every, setTimeout as sleep } from 'node:timers/promises';
import { openDatabase } from './db.ts';
import {
  claimNext,
  clearHeartbeat,
  completeJob,
  failAttempt,
  requeueInterrupted,
  setProgress,
  writeHeartbeat,
  type JobRow,
} from './jobs.ts';

const STEP_MS = 100;
const IDLE_MS = 200;
const HEARTBEAT_MS = 1000;
const RETRY_DELAY_MS = 500;

const db = openDatabase();
let stopping = false;

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

/** Processes one attempt. A stop request leaves the job `running`; it is requeued on the next start. */
async function runAttempt(job: JobRow): Promise<void> {
  // Attempt n fails at its first step, before any progress, when n <= failAttempts.
  if (job.attempts <= job.fail_attempts) {
    failAttempt(db, job, Date.now(), RETRY_DELAY_MS);
    return;
  }
  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) return;
    setProgress(db, job.seq, step);
  }
  completeJob(db, job.seq, job.input.toUpperCase());
}

// A worker that starts while no other worker is running owns every job still marked running.
const requeued = requeueInterrupted(db);
if (requeued > 0) console.log(`requeued ${requeued} interrupted job(s)`);

writeHeartbeat(db, Date.now());
const heartbeat = (async () => {
  for await (const _ of every(HEARTBEAT_MS)) {
    if (stopping) break;
    try {
      writeHeartbeat(db, Date.now());
    } catch (err) {
      console.error('heartbeat failed:', err);
    }
  }
})();

console.log('worker started');
while (!stopping) {
  try {
    const job = claimNext(db, Date.now());
    if (job) await runAttempt(job);
    else await sleep(IDLE_MS);
  } catch (err) {
    console.error('worker iteration failed:', err);
    await sleep(IDLE_MS);
  }
}

await heartbeat;
clearHeartbeat(db);
db.close();
console.log('worker stopped');

